from lib import *
S = SS('s27')
steps = [
    step("服务器把同一段 12,026 字节的 HTML 用不同的 Content-Encoding 发出,Scrapy 都解压回原文:gzip(116 字节传输)、x-gzip、deflate(zlib 封装 104 字节;裸 deflate 98 字节也能解)、br(55 字节)、zstd(74 字节)、叠加的 'gzip, br'(120 字节,先按 br 解、再按 gzip 解),回调拿到的 body 全是 12,026 字节、与原文一致,Content-Encoding 头被删掉,响应类是 HtmlResponse。压缩是 Python 3.14 自带的 compression.zstd 和 brotli 库解的。 出问题的几种情形:不支持的 compress 编码原样保留(body 10 字节,Content-Encoding 仍是 compress,响应类退成普通 Response,日志 WARNING “HttpCompressionMiddleware cannot decode the response … from unsupported encoding(s) 'compress'”);服务器声称 gzip 其实没压缩,抛 BadGzipFile: Not a gzipped file,走 errback;截断的 gzip(只有前 60 字节)不报错,回调拿到解出来的 28 字节;没有压缩的正常。stats:httpcompression/response_count = 9,response_bytes = 84,220(包含 compress 的 10 字节原样和截断的 28 字节)。", t=tl(S(1)), mark=lidx(S(1), '不支持的 compress', '声称 gzip', '截断的 gzip'), done=lidx(S(1), 'gzip   ', 'br  ', 'zstd  ', '叠加 gzip, br'), b=bars([['gzip 传输', 116, '116 字节'], ['br 传输', 55, '55 字节'], ['zstd 传输', 74, '74 字节'], ['解压后', 12026, '12,026 字节']], 12026, mark=[3], done=[0, 1, 2]), kv=KV([['支持的编码', 'gzip、x-gzip、deflate(含裸)、br、zstd'], ['叠加编码', '按相反顺序依次解'], ['不支持的编码', '原样保留 + WARNING'], ['假 gzip / 截断的 gzip', 'BadGzipFile / 返回已解出部分']], ['叠加编码'])),
    step("解压炸弹:20,406 字节的 gzip 解压成 20,971,520 字节(20 MiB)。默认 DOWNLOAD_MAXSIZE = 1 GiB、DOWNLOAD_WARNSIZE = 32 MiB,回调正常拿到 20,971,520 字节;DOWNLOAD_WARNSIZE = 10 MiB 时仍然拿到,但多一条 WARNING “body size after decompression (20971520 B) is larger than the download warning size”;DOWNLOAD_MAXSIZE = 10 MiB 时响应被丢弃,日志 “Ignored response … because its body (20406 B compressed, …)”,errback 收到 IgnoreRequest。解压是分块做的(64 KiB 一块),超过上限就停,不会把整个炸弹解到内存里。", t=tl(S(2)), mark=lidx(S(2), 'WARNSIZE = 10', 'MAXSIZE = 10'), done=lidx(S(2), '默认', '服务器发送'), b=bars([['压缩体', 20406, '20,406 字节'], ['解压后', 20971520, '20,971,520 字节']], 20971520, mark=[1], done=[0]), kv=KV([['默认', '1 GiB 上限,32 MiB 警告'], ['WARNSIZE', '超过只警告'], ['MAXSIZE', '超过丢弃,errback IgnoreRequest']], ['MAXSIZE'])),
    step("HEAD 请求不解压:回调 body 为空、Content-Encoding 头仍是 gzip。COMPRESSION_ENABLED = 0 时不再发 Accept-Encoding(服务器看到 None),但服务器照样发了 gzip,回调拿到 116 字节压缩体(开头 1f8b 是 gzip 魔数),Content-Encoding = gzip 保留——关掉中间件后要自己解压。", t=tl(S(3)), mark=lidx(S(3), 'COMPRESSION_ENABLED = 0'), done=lidx(S(3), 'HEAD'), kv=KV([['HEAD', '不解压,头保留'], ['COMPRESSION_ENABLED = 0', '不发 Accept-Encoding,不解压'], ['服务器仍发 gzip', '回调拿到压缩字节']], ['COMPRESSION_ENABLED = 0'])),
]
A = mkarts('s27', 27, 'Scrapy,HttpCompressionMiddleware,gzip,brotli,zstd,解压炸弹,真实验证,动画演示',
    '实测 HttpCompressionMiddleware:gzip、x-gzip、deflate(含裸 deflate)、br、zstd 和叠加编码都能解回 12,026 字节原文;不支持的 compress 原样保留并警告,假 gzip 抛 BadGzipFile,截断的 gzip 返回已解出的部分;DOWNLOAD_MAXSIZE 拦住 20 KB 解成 20 MiB 的炸弹,DOWNLOAD_WARNSIZE 只警告。',
    '服务器发来压缩的响应,Scrapy 自己解压。支持哪些编码?叠加编码怎么处理?压缩体坏了、编码不认识会怎样?别人发一个 20 KB 的炸弹包要解压成 20 MB,能防住吗?这篇逐个实测。',
    [('5 种', '2.19 能解的 Content-Encoding(gzip/x-gzip、deflate、br、zstd;外加叠加)'), ('20,406 → 20,971,520', '解压炸弹测试里压缩体与解压后的字节数'), ('BadGzipFile', '服务器声称 gzip 其实没压缩时的错误')],
    [('支持的编码与异常情形', '<p>请求里的 <code>Accept-Encoding</code> 写死 <code>gzip, deflate, br, zstd</code>。响应按 <code>Content-Encoding</code> 解压,叠加编码从最后一个往前解,裸 deflate 也能处理;解出的 body 替换原 body,<code>Content-Encoding</code> 头被删除,响应类重新判定。不认识的编码原样保留并警告;数据损坏会抛出对应的异常(如 <code>BadGzipFile</code>),由 errback 接住;被截断的流返回已解出的部分。</p>'),
     ('大小保护', '<p>解压按块进行,超过 <code>DOWNLOAD_MAXSIZE</code> 就放弃并丢弃响应;超过 <code>DOWNLOAD_WARNSIZE</code> 只记警告。默认上限 1 GiB、警告 32 MiB。</p>'),
     ('例外', '<p>HEAD 请求不解压;<code>COMPRESSION_ENABLED = 0</code> 时不发 <code>Accept-Encoding</code> 也不解压。</p>')],
    steps,
    [ENV_Y + '(brotli 1.2.0,Python 3.14 自带 compression.zstd)。服务器用 gzip、zlib、brotli、compression.zstd 压缩同一段文本;炸弹是 20 MiB 的重复字节 gzip 后',
     '没有验证:Python < 3.14 时 zstd 需要 backports.zstd;brotlicffi 回退;流式下载大文件时的压缩(stream);Transfer-Encoding: chunked 与压缩的组合;aiohttp / httpx 下载处理器自带的解压是否与中间件重复;真实站点上 Content-Encoding 头大小写、多值头的各种写法'],
    '压缩响应')
